typedef struct Edge {
    int to;
    struct Edge *next;
} Edge;

Edge *adj[MAXN];
int color[MAXN];
int count[2];
int is_bipartite;

void add_edge(int u, int v) {
    Edge *e = (Edge*)malloc(sizeof(Edge));
    e->to = v;
    e->next = adj[u];
    adj[u] = e;
}

void dfs(int u, int c) {
    color[u] = c;
    count[c]++;
    for (Edge *e = adj[u]; e; e = e->next) {
        int v = e->to;
        if (color[v] == -1) {
            dfs(v, 1 - c);
        } else if (color[v] == c) {
            is_bipartite = 0;
        }
    }
}

