typedef long long ll;

typedef struct {
    int to, next;
} Edge;

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int maxE = 2 * M + 5;
    Edge *edges = (Edge *)malloc(sizeof(Edge) * maxE);
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    int *deg = (int *)calloc(N + 1, sizeof(int));
    int *U = (int *)malloc(sizeof(int) * M);
    int *V = (int *)malloc(sizeof(int) * M);

    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        U[i] = a; V[i] = b;

        edges[ecnt].to = b; edges[ecnt].next = head[a]; head[a] = ecnt++;
        edges[ecnt].to = a; edges[ecnt].next = head[b]; head[b] = ecnt++;

        deg[a]++; deg[b]++;
    }

    // Check bipartiteness
    int *color = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) color[i] = -1;

    int *queue = (int *)malloc(sizeof(int) * (N + 5));
    int qh = 0, qt = 0;

    color[1] = 0;
    queue[qt++] = 1;
    ll cnt[2] = {1, 0};
    int bip = 1;

    while (qh < qt) {
        int u = queue[qh++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (color[v] == -1) {
                color[v] = color[u] ^ 1;
                cnt[color[v]]++;
                queue[qt++] = v;
            } else if (color[v] == color[u]) {
                bip = 0;
            }
        }
    }

    ll ans;
    if (bip) {
        // In a connected bipartite graph, vertices reachable by odd length 3
        // are exactly vertices in the opposite partition.
        // So final graph can be complete bipartite between the two partitions.
        ans = cnt[0] * cnt[1] - M;
    } else {
        // In a connected non-bipartite graph, every pair of distinct vertices
        // can eventually be connected (there exists an odd walk, and by adding
        // edges repeatedly we can make the graph complete).
        ans = (ll)N * (N - 1) / 2 - M;
    }

    printf("%lld\n", ans);

    free(edges);
    free(head);
    free(deg);
    free(U);
    free(V);
    free(color);
    free(queue);
    return 0;
}

