int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    vector<vector<int>> adj(N);
    for (int i = 0; i < M; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    vector<bool> visited(N, false);
    long long totalEdges = 0;

    for (int i = 0; i < N; i++) {
        if (!visited[i]) {
            // BFS to find component size
            queue<int> q;
            q.push(i);
            visited[i] = true;
            long long sz = 0;
            long long compEdges = 0;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                sz++;
                for (int v : adj[u]) {
                    compEdges++;
                    if (!visited[v]) {
                        visited[v] = true;
                        q.push(v);
                    }
                }
            }
            // Each edge counted twice in compEdges
            compEdges /= 2;
            long long possible = sz * (sz - 1) / 2;
            totalEdges += possible - compEdges;
        }
    }

    cout << totalEdges << "\n";
    return 0;
}

