int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> g(N);
    vector<pair<int,int>> edges;
    edges.reserve(M);

    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
        edges.push_back({a, b});
    }

    // Color the graph by parity from an arbitrary root.
    // Because the graph is connected:
    // - If it is bipartite, then vertices split into two parts.
    //   A walk of odd length (3) goes between different parts.
    //   Thus any missing cross-part edge can eventually be added.
    // - If it is not bipartite, then the graph is non-bipartite connected,
    //   hence there exists an odd cycle, and every pair of distinct vertices
    //   can be connected by a walk of length 3 after enough additions.
    //   Therefore we can make the graph complete.
    vector<int> color(N, -1);
    queue<int> q;
    color[0] = 0;
    q.push(0);
    bool bipartite = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : g[u]) {
            if (color[v] == -1) {
                color[v] = color[u] ^ 1;
                q.push(v);
            } else if (color[v] == color[u]) {
                bipartite = false;
            }
        }
    }

    long long maxEdges;
    if (bipartite) {
        long long c0 = 0, c1 = 0;
        for (int x : color) {
            if (x == 0) ++c0;
            else ++c1;
        }
        maxEdges = c0 * c1;
    } else {
        maxEdges = 1LL * N * (N - 1) / 2;
    }

    cout << (maxEdges - M) << '\n';
    return 0;
}

