import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();

        List<Integer>[] adj = new ArrayList[N];
        for (int i = 0; i < N; i++) adj[i] = new ArrayList<>();
        boolean[][] edge = new boolean[N][N];

        for (int i = 0; i < M; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            adj[a].add(b);
            adj[b].add(a);
            edge[a][b] = edge[b][a] = true;
        }

        long added = 0;
        boolean[] visited = new boolean[N];
        int[] dist = new int[N];

        for (int start = 0; start < N; start++) {
            Arrays.fill(visited, false);
            Arrays.fill(dist, -1);
            Queue<Integer> q = new LinkedList<>();
            q.add(start);
            visited[start] = true;
            dist[start] = 0;

            while (!q.isEmpty()) {
                int u = q.poll();
                if (dist[u] == 3) continue;
                for (int v : adj[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        dist[v] = dist[u] + 1;
                        q.add(v);
                    }
                }
            }

            for (int v = 0; v < N; v++) {
                if (v != start && dist[v] == 3 && !edge[start][v]) {
                    added++;
                }
            }
        }

        System.out.println(added / 2);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int M = fs.nextInt();

        ArrayList<Integer>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            g[a].add(b);
            g[b].add(a);
        }

        // Color graph by parity (bipartite coloring).
        // Since the graph is connected, if it is bipartite then the bipartition is unique up to swap.
        int[] color = new int[N];
        Arrays.fill(color, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        boolean bipartite = true;

        color[0] = 0;
        q.add(0);

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g[u]) {
                if (color[v] == -1) {
                    color[v] = color[u] ^ 1;
                    q.add(v);
                } else if (color[v] == color[u]) {
                    bipartite = false;
                }
            }
        }

        long ans;
        if (!bipartite) {
            // In a connected non-bipartite graph, every vertex can reach every other vertex
            // by a walk of any sufficiently large length; in particular, exactly length 3.
            // Therefore we can eventually add all missing edges.
            ans = (long) N * (N - 1) / 2 - M;
        } else {
            // In a bipartite graph, a walk of odd length goes only between opposite partitions.
            // So only cross-partition edges can ever be added, and finally the graph becomes complete bipartite.
            long c0 = 0, c1 = 0;
            for (int x : color) {
                if (x == 0) c0++;
                else c1++;
            }
            ans = c0 * c1 - M;
        }

        System.out.println(ans);
    }
}
